import {html} from 'lit-html'
import type {RootRule, Rule} from '../yaml-rule-util'

const nameRule: Rule = {
  description: 'A custom name for this prompt',
  single: ['string'],
}

const descriptionRule: Rule = {
  description: 'A description of this prompt',
  single: ['string'],
}

const modelRule: Rule = {
  description: 'The model to use',
  single: ['string'],
}

const modelParametersRule: Rule = {
  description: "Parameters for configuring the model's behavior",
  map: {
    single: ['string', 'number', 'boolean'],
  },
}

const messageRoleRule: Rule = {
  description: 'The chat role associated with this message',
  values: ['assistant', 'developer', 'system', 'user'],
  required: true,
}

const messageContentRule: Rule = {
  description: 'The content of the message',
  single: ['string'],
  required: true,
}

const messagesRule: Rule = {
  description:
    'The collection of context messages associated with this chat completion request. Typical usage begins with a chat message for the System role that provides instructions for the behavior of the assistant, followed by alternating messages between the User and Assistant roles.',
  multipleValues: true,
  required: true,
  items: {
    rules: {
      role: messageRoleRule,
      content: messageContentRule,
    },
  },
}

const testDataInputRule: Rule = {
  description: 'The input string to test',
  single: ['string'],
}

const testDataExpectedRule: Rule = {
  description: 'The expected output for this input',
  single: ['string'],
}

const testDataRule: Rule = {
  description: 'Specify inputs and expected outputs for evaluating the prompt',
  multipleValues: true,
  items: {
    rules: {
      input: testDataInputRule,
      expected: testDataExpectedRule,
    },
  },
}

const evaluatorsRule: Rule = {
  description: 'A list of evaluators that test the output of a prompt',
  multipleValues: true,
  items: {
    single: ['string'],
    rules: {
      name: {
        description: 'A name for this evaluator',
        single: ['string'],
        required: true,
      },
      string: {
        description: 'Check if the output contains a specific string',
        rules: {
          contains: {
            single: ['string'],
          },
          strict: {
            description: 'Is the value case-sensitive',
            single: ['boolean'],
          },
          startsWith: {
            single: ['string'],
          },
          endsWith: {
            single: ['string'],
          },
        },
      },
      uses: {
        description: 'A predefined behavior for this evaluator',
        single: ['string'],
        async validateValue(_yaml, _path, value) {
          if (typeof value !== 'string')
            return {
              severity: 'error',
              message: html`A single string is required`,
            }
          if (!/^github\/\w+$/.test(value)) {
            return {
              severity: 'error',
              message: html`Currently only GitHub behaviors are supported`,
            }
          }

          return undefined
        },
      },
      llm: {
        description: 'Create a test criteria by writing your own prompt',
        rules: {
          modelId: {
            single: ['string'],
            required: true,
          },
          prompt: {
            single: ['string'],
          },
          systemPrompt: {
            single: ['string'],
          },
          modelParameters: modelParametersRule,
          choices: {
            multipleValues: true,
            items: {
              rules: {
                choice: {
                  single: ['string'],
                  required: true,
                },
                score: {
                  single: ['number'],
                  required: true,
                },
              },
            },
          },
        },
      },
    },
  },
}

function fullRootRule(): RootRule {
  return {
    rules: {
      name: nameRule,
      description: descriptionRule,
      model: modelRule,
      modelParameters: modelParametersRule,
      messages: messagesRule,
      testData: testDataRule,
      evaluators: evaluatorsRule,
    },
  }
}

export function getRootRule(): RootRule {
  const rule = fullRootRule()
  return rule
}
