import {isFeatureEnabled} from '@github-ui/feature-flags'
import {AlphaLabel} from '@github-ui/lifecycle-labels/alpha'
import {Flash, Label, Link} from '@primer/react'

import styles from './CustomSlashCommandsBanner.module.css'

export function CustomSlashCommandsBanner({customSlashCommandsDocsUrl}: {customSlashCommandsDocsUrl: string}) {
  const lifecycleLabelNameEnabled = isFeatureEnabled('lifecycle_label_name_updates')
  return (
    <Flash className={styles.Flash}>
      {lifecycleLabelNameEnabled ? (
        <AlphaLabel className="mr-2" />
      ) : (
        <Label variant="success" className={styles.Label}>
          Alpha
        </Label>
      )}
      Looks like this file is a custom slash command. Need help? Check out the{' '}
      <Link inline href={customSlashCommandsDocsUrl}>
        documentation
      </Link>
      .
    </Flash>
  )
}

try{ CustomSlashCommandsBanner.displayName ||= 'CustomSlashCommandsBanner' } catch {}